TWComponent.script:
try{
tw.local.Seperated = new tw.object.listOf.String();
tw.local.Seperated = tw.local.data.split("-");

tw.local.invoiceNo	= tw.local.Seperated[0];
tw.local.cif 		= tw.local.Seperated[1];
}
catch (err) {
	tw.local.errorMSG = err.message;
	throw new Error(tw.local.errorMSG);	
}

/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value){
	if(value == null && typeof value == "string"){
		value= ""; 
	}
	else if(value == null && typeof value == "number"){
		value= 0;
	}
	else if(value == null && typeof value == "boolean"){
		value = "0";
	}
 var parameter = new tw.object.SQLParameter();  
   parameter.value = value;
   parameter.mode = "IN";
return parameter;
}
/***********************************************************************************/

tw.local.sql = "SELECT REQUESRID FROM "+ tw.env.LKP_DB_Schema +".ODC_INVOICE WHERE INVOICENO=? AND REQUESRID NOT IN ( SELECT ID FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE (REQUESTSTATUS='"
			+ tw.epv.Status.Canceled +"' OR REQUESTSTATUS='"+ tw.epv.Status.terminated +"') AND CIF =? )";
tw.local.parameters = new tw.object.listOf.SQLParameter();

tw.local.parameters.insertIntoList(tw.local.parameters.listLength,  addSQLParameter(tw.local.invoiceNo));
tw.local.parameters.insertIntoList(tw.local.parameters.listLength,  addSQLParameter(tw.local.cif));

